1	// Graph-first PM view over the decision-graph API (served by the backend at /ui, same origin).
2	import { layout, STAGE } from "./layout.js";
3	import { createStart } from "./start.js";
4	
5	const $ = (sel) => document.querySelector(sel);
6	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
7	const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + "…" : s);
8	
9	let graph = { nodes: [], edges: [] };
10	let view = {}; // derived lookups, rebuilt on every load
11	let selected = null;
12	let lastPos = {}; // layout positions of the current render (drag-to-connect snaps back to them)
13	// Modes that turn graph clicks into picks instead of selection:
14	let draft = null; // {type, inputs: [ids], relation}: the "new node" form is open
15	let linking = null; // {from, to}: connect `from` as a new input of `to`
16	// Focus mode: the graph shows only the chain of focusId (what it's built on + what's built on
17	// it), so it stays readable at any size. Off = the whole graph with the chain highlighted.
18	let focusMode = true;
19	let focusId = null;
20	let showOld = false; // old versions are hidden unless something current still builds on them
21	let drawnSig = ""; // which nodes are drawn: refit the view only when that changes
22	let sideTab = "inbox";
23	
24	const store = {
25	  get: (k) => { try { return localStorage.getItem(k); } catch { return null; } },
26	  set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* storage blocked */ } },
27	};
28	let lastSeen = store.get("lastSeen"); // ISO time of the PM's last "mark as seen"; null = first visit
29	const isBrief = (n) => n.type === "Note" && n.content?.kind === "brief";
30	
31	const COLORS = Object.fromEntries(
32	  Object.keys(STAGE).map((t) => [t, getComputedStyle(document.documentElement).getPropertyValue(`--${t}`).trim()]),
33	);
34	
35	const cy = cytoscape({
36	  container: $("#graph"),
37	  minZoom: 0.2,
38	  maxZoom: 2.5,
39	  style: [
40	    { selector: "node", style: {
41	      shape: "round-rectangle", width: 210, height: 64, "background-color": (n) => COLORS[n.data("type")],
42	      label: "data(label)", "text-wrap": "wrap", "text-max-width": 196, "font-size": 11,
43	      "text-valign": "center", color: "#0f172a", "border-width": 1, "border-color": "#cbd5e1",
44	    } },
45	    { selector: "node.stale", style: { "border-width": 3, "border-style": "dashed", "border-color": "#f97316" } },
46	    { selector: "node.superseded", style: { opacity: 0.45 } },
47	    { selector: "node.approve", style: { "border-width": 4, "border-color": "#16a34a" } },
48	    { selector: "node.reject", style: { "border-width": 4, "border-color": "#dc2626" } },
49	    { selector: "node.postpone", style: { "border-width": 4, "border-color": "#a16207" } },
50	    { selector: "node.awaiting", style: { "border-width": 4, "border-style": "double", "border-color": "#7c3aed" } },
51	    { selector: "node.picked", style: { "border-width": 5, "border-style": "solid", "border-color": "#2563eb" } },
52	    { selector: "node:selected", style: { "overlay-color": "#2563eb", "overlay-opacity": 0.15, "overlay-padding": 6 } },
53	    { selector: "edge", style: {
54	      width: 1.5, "line-color": "#94a3b8", "target-arrow-color": "#94a3b8", "target-arrow-shape": "triangle",
55	      "curve-style": "bezier", "font-size": 9, color: "#64748b", "text-background-color": "#f8fafc",
56	      "text-background-opacity": 1,
57	    } },
58	    { selector: "edge.contradicts", style: { "line-color": "#dc2626", "target-arrow-color": "#dc2626", label: "contradicts" } },
59	    { selector: "edge.supports", style: { "line-color": "#16a34a", "target-arrow-color": "#16a34a", label: "supports" } },
60	    { selector: "edge.scores", style: { "line-style": "dashed", label: "scores" } },
61	    { selector: "edge.version", style: { "line-style": "dotted", "line-color": "#f97316", "target-arrow-color": "#f97316", label: "new version" } },
62	    { selector: ".faded", style: { opacity: 0.12 } },
63	  ],
64	});
65	
66	window.cy = cy; // for debugging in the browser console and for UI tests
67	
68	// ---- API ---------------------------------------------------------------
69	
70	async function api(path, body) {
71	  const resp = await fetch(path, body && {
72	    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
73	  });
74	  const data = await resp.json().catch(() => ({}));
75	  if (!resp.ok) throw new Error(typeof data.detail === "string" ? data.detail : JSON.stringify(data.detail ?? resp.statusText));
76	  return data;
77	}
78	
79	function toast(msg, isError = false) {
80	  const t = $("#toast");
81	  t.textContent = msg;
82	  t.className = isError ? "error" : "";
83	  clearTimeout(toast.timer);
84	  toast.timer = setTimeout(() => { t.textContent = ""; }, isError ? 8000 : 3000);
85	}
86	
87	// ---- data --------------------------------------------------------------
88	
89	async function load() {
90	  const [nodes, edges] = await Promise.all([api("/nodes"), api("/edges")]);
91	  // polling during agent runs calls this every 1.5 s: only redraw when something changed
92	  const sig = nodes.map((n) => n.id + n.status).join() + edges.length;
93	  if (sig === load.sig) return;
94	  load.sig = sig;
95	  graph = { nodes, edges };
96	  view = derive(nodes, edges);
97	  if (lastSeen === null) { // first visit: what's there now counts as seen
98	    lastSeen = nodes.length ? nodes.at(-1).timestamp : new Date(0).toISOString();
99	    store.set("lastSeen", lastSeen);
100	  }
101	  render();
102	}
103	
104	function derive(nodes, edges) {
105	  const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
106	  const decisionsFor = {}, supersededBy = {}, inputs = {}, dependents = {};
107	  for (const e of edges) {
108	    (inputs[e.from_id] ??= []).push(e);
109	    // decisions show up as the target's verdict, not in its "Used by" list
110	    if (e.relation === "decides") (decisionsFor[e.to_id] ??= []).push(byId[e.from_id]);
111	    else (dependents[e.to_id] ??= []).push(e);
112	  }
113	  for (const n of nodes) if (n.replaces) supersededBy[n.replaces] = n.id;
114	  const brief = nodes.filter((n) => isBrief(n) && !supersededBy[n.id]).at(-1) ?? null;
115	  return { byId, decisionsFor, supersededBy, inputs, dependents, brief };
116	}
117	
118	const latestOf = (id) => { while (view.supersededBy[id]) id = view.supersededBy[id]; return id; };
119	
120	/** Everything id is (transitively) built on. */
121	function upstream(id) {
122	  const seen = new Set();
123	  const todo = [id];
124	  while (todo.length) {
125	    for (const e of view.inputs[todo.pop()] || []) if (!seen.has(e.to_id)) { seen.add(e.to_id); todo.push(e.to_id); }
126	  }
127	  return seen;
128	}
129	
130	/** id's chain: what it's built on, what's built on it, and the other versions of those. */
131	function chainIds(id) {
132	  const chain = new Set([id, ...upstream(id), ...builtOn(id)]);
133	  for (const c of [...chain]) {
134	    for (let v = c; view.supersededBy[v]; v = view.supersededBy[v]) chain.add(view.supersededBy[v]);
135	    // older versions + what still hangs off them: the stale nodes an edit broke belong to its chain
136	    for (let v = view.byId[c]?.replaces; v; v = view.byId[v]?.replaces) {
137	      chain.add(v);
138	      for (const d of builtOn(v)) chain.add(d);
139	    }
140	  }
141	  return chain;
142	}
143	
144	/** For a stale node: the edit upstream that broke it, as "EVD-001 was edited → EVD-005". */
145	function brokenBy(id) {
146	  const edited = [...upstream(id)].find((u) => view.supersededBy[u]);
147	  return edited ? { old: edited, now: latestOf(edited) } : null;
148	}
149	
150	const summary = (n) => {
151	  const c = n.content || {};
152	  if (c.rows) return `${c.file ?? "file"} · ${c.rows.length} rows`;
153	  return String(c.text ?? c.quote ?? c.file ?? c.verdict ?? JSON.stringify(c));
154	};
155	const verdictOf = (id) => (view.decisionsFor[id] || []).at(-1)?.content?.verdict;
156	
157	// ---- graph -------------------------------------------------------------
158	
159	function visibleNodes() {
160	  let ns = graph.nodes.filter((n) => n.type in STAGE && !isBrief(n)); // the brief lives in the brief bar
161	  if (!showOld) { // an old version stays only while something current still builds on it (explains a stale node)
162	    ns = ns.filter((n) => !view.supersededBy[n.id] || n.id === focusId
163	      || (view.dependents[n.id] || []).some((e) => !view.supersededBy[e.from_id]));
164	  }
165	  if (focusId && view.byId[focusId]) {
166	    const chain = chainIds(focusId);
167	    ns = ns.filter((n) => chain.has(n.id));
168	  }
169	  return ns;
170	}
171	
172	function render() {
173	  if (focusMode && selected && view.byId[selected]) focusId = selected;
174	  else if (!draft && !linking) focusId = null;
175	  renderGraph();
176	  if (!graph.nodes.length || forceStart) guard(start.show)({ name: $("#pm").value });
177	  else start.hide();
178	  renderStats();
179	  renderJump();
180	  renderBrief();
181	  renderSide();
182	  if (draft || linking) markPicked(); // an open form must survive redraws (e.g. agent polling)
183	  else if (selected && view.byId[selected]) highlight();
184	  else showHint(false);
185	  renderTimeline();
186	}
187	
188	function renderGraph() {
189	  const drawn = visibleNodes();
190	  const pos = layout(drawn, graph.edges);
191	  lastPos = pos;
192	  const sig = drawn.map((n) => n.id).join();
193	  const changed = sig !== drawnSig; // new nodes (e.g. mid agent run) or a new focus must be in view
194	  drawnSig = sig;
195	  cy.elements().remove();
196	  cy.add(drawn.map((n) => ({
197	    group: "nodes",
198	    data: { id: n.id, type: n.type, label: `${n.id}${n.version > 1 ? ` v${n.version}` : ""}\n${short(summary(n), 70)}` },
199	    position: pos[n.id],
200	    classes: [n.status === "stale" && "stale", view.supersededBy[n.id] && "superseded", verdictOf(n.id),
201	      waitingOn(n) && "awaiting"].filter(Boolean).join(" "),
202	  })));
203	  const isDrawn = (id) => id in pos;
204	  // arrows follow the chain (input -> derived), except "X supports/contradicts Y", which points at Y
205	  const pointsAtInput = (e) => e.relation === "supports" || e.relation === "contradicts";
206	  cy.add(graph.edges.filter((e) => isDrawn(e.from_id) && isDrawn(e.to_id)).map((e, i) => ({
207	    group: "edges",
208	    data: { id: `e${i}`, source: pointsAtInput(e) ? e.from_id : e.to_id, target: pointsAtInput(e) ? e.to_id : e.from_id },
209	    classes: e.relation,
210	  })));
211	  cy.add(drawn.filter((n) => n.replaces && isDrawn(n.replaces)).map((n) => ({
212	    group: "edges", data: { id: `v-${n.id}`, source: n.replaces, target: n.id }, classes: "version",
213	  })));
214	  renderFocusbar(drawn.length);
215	  if (changed) requestAnimationFrame(fitView); // after the page layout settled (first load, focus bar height)
216	}
217	
218	function fitView() {
219	  cy.resize();
220	  cy.fit(undefined, 40);
221	  if (cy.zoom() > 1) { cy.zoom(1); cy.center(); } // a 2-node graph shouldn't fill the screen
222	}
223	
224	function renderFocusbar(count) {
225	  const old = `<label><input type="checkbox" id="showOld" ${showOld ? "checked" : ""}> show old versions</label>`;
226	  $("#focusbar").innerHTML = focusId
227	    ? `<span>Chain of <b>${esc(focusId)}</b>: what it's built on and what's built on it (${count} nodes)</span>
228	       <button type="button" data-focus="off">Show whole graph</button>${old}`
229	    : `<span>Whole graph · ${count} nodes</span>
230	       ${selected ? `<button type="button" data-focus="on">Focus on ${esc(selected)}'s chain</button>`
231	         : `<span>Click a node or an inbox item to see only its chain.</span>`}${old}`;
232	}
233	
234	function renderStats() {
235	  const count = (pred) => graph.nodes.filter(pred).length;
236	  const decided = Object.keys(view.decisionsFor).length;
237	  $("#stats").textContent = [
238	    `${graph.nodes.length} nodes`,
239	    `${count((n) => n.type === "Requirement" && !view.supersededBy[n.id])} requirements`,
240	    `${decided} decided`,
241	    `${count((n) => n.status === "stale" && !view.supersededBy[n.id])} stale`,
242	    `${count((n) => waitingOn(n) === "pm")} questions for you`,
243	    `${count((n) => waitingOn(n) === "agent")} waiting for the agent`,
244	  ].join(" · ");
245	}
246	
247	function nodeOptions(current = null) {
248	  const groups = {};
249	  for (const n of graph.nodes) (groups[n.type] ??= []).push(n);
250	  return `<option value="">—</option>` + Object.entries(groups).map(([type, ns]) =>
251	    `<optgroup label="${esc(type)}">${ns.map((n) =>
252	      `<option value="${esc(n.id)}" ${n.id === current ? "selected" : ""}>${esc(n.id)} — ${esc(short(summary(n), 50))}</option>`,
253	    ).join("")}</optgroup>`).join("");
254	}
255	
256	function renderJump() {
257	  $("#jump").innerHTML = nodeOptions(selected);
258	}
259	
260	// ---- work lists: inbox + requirements ----------------------------------
261	// The PM's loop: inbox -> click an item -> its chain -> act -> next item; empty inbox -> Run agent.
262	
263	function inboxGroups() {
264	  const live = graph.nodes.filter((n) => !view.supersededBy[n.id] && !isBrief(n) && n.type !== "Decision");
265	  const seen = new Date(lastSeen || 0);
266	  const broke = (n) => {
267	    const b = brokenBy(n.id);
268	    return b ? `${esc(b.old)} was edited → ${esc(b.now)}` : "something it is built on changed";
269	  };
270	  return [
271	    { key: "asks", title: "The agent asks you", hint: "Answer so it can continue.",
272	      items: live.filter((n) => waitingOn(n) === "pm") },
273	    { key: "broken", title: "Broken by an edit", hint: "Built on something that changed. The agent redoes them on its next run.",
274	      items: live.filter((n) => n.status === "stale"), why: broke,
275	      action: { label: "Let the agent redo these", run: runAgent, primary: true } },
276	    { key: "decide", title: "Waiting for your decision", hint: "Proposed requirements: approve, reject or postpone.",
277	      items: live.filter((n) => n.type === "Requirement" && n.status !== "stale" && !verdictOf(n.id)) },
278	    { key: "agent", title: "Waiting for the agent", hint: "Your requests; handled first on the next run.",
279	      items: live.filter((n) => waitingOn(n) === "agent"), action: { label: "Run agent", run: runAgent } },
280	    { key: "new", title: "New since your last visit",
281	      items: live.filter((n) => !n.created_by.startsWith("PM:") && new Date(n.timestamp) > seen),
282	      why: (n) => esc(n.rationale ? short(n.rationale, 90) : ""), action: { label: "Mark all as seen", run: markSeen } },
283	  ];
284	}
285	
286	function itemHtml(n, why = "") {
287	  const verdict = verdictOf(n.id);
288	  return `<button type="button" class="item ${n.id === selected ? "current" : ""}" data-goto="${esc(n.id)}">
289	    <span class="head"><span class="pill ${esc(n.type)}">${esc(n.id)}</span>
290	      ${verdict ? `<span class="pill ${esc(verdict)}">${esc(verdict)}</span>` : ""}
291	      ${n.status === "stale" ? `<span class="pill stale">stale</span>` : ""}</span>
292	    <span class="text">${esc(short(summary(n), 110))}</span>
293	    ${why ? `<span class="why">${why}</span>` : ""}</button>`;
294	}
295	
296	const MAX_ITEMS = 8;
297	
298	function renderSide() {
299	  const groups = inboxGroups();
300	  renderSide.actions = Object.fromEntries(groups.filter((g) => g.action).map((g) => [g.key, g.action.run]));
301	  const html = groups.filter((g) => g.items.length).map((g) => `
302	    <section class="group ${g.key}">
303	      <h3><span class="dot"></span>${esc(g.title)} (${g.items.length})</h3>
304	      ${g.hint ? `<p class="hint">${esc(g.hint)}</p>` : ""}
305	      ${g.items.slice(0, MAX_ITEMS).map((n) => itemHtml(n, g.why?.(n))).join("")}
306	      ${g.items.length > MAX_ITEMS ? `<p class="meta">+${g.items.length - MAX_ITEMS} more</p>` : ""}
307	      ${g.action ? `<button type="button" class="group-action ${g.action.primary ? "primary" : ""}" data-group="${g.key}">${esc(g.action.label)}</button>` : ""}
308	    </section>`).join("");
309	  $("#inbox").innerHTML = html || (graph.nodes.length
310	    ? `<p class="hint">Nothing needs you right now.</p>
311	       <button type="button" class="group-action primary" data-group="run">Run the agent to continue</button>`
312	    : `<p class="hint">Start a project in the middle panel.</p>`);
313	  const needsPm = groups.filter((g) => ["asks", "broken", "decide"].includes(g.key)).reduce((s, g) => s + g.items.length, 0);
314	  $("#inboxCount").textContent = needsPm || "";
315	  $("#inboxCount").classList.toggle("hot", needsPm > 0);
316	  renderReqs();
317	}
318	
319	const REQ_ORDER = { undecided: 0, postpone: 1, approve: 2, reject: 3 };
320	
321	function renderReqs() {
322	  const reqs = graph.nodes.filter((n) => n.type === "Requirement" && !view.supersededBy[n.id])
323	    .map((n) => ({ n, v: verdictOf(n.id) || "undecided" }))
324	    .sort((a, b) => (b.n.status === "stale") - (a.n.status === "stale") || REQ_ORDER[a.v] - REQ_ORDER[b.v]);
325	  $("#reqCount").textContent = reqs.length || "";
326	  $("#reqs").innerHTML = reqs.map(({ n, v }) => {
327	    const up = [...upstream(n.id)].map((id) => view.byId[id]);
328	    const evidence = up.filter((u) => u.type === "Evidence").length;
329	    const sources = up.filter((u) => u.type === "Source").length;
330	    return itemHtml(n, `${v === "undecided" ? `<span class="pill none">undecided</span> ` : ""}${evidence} evidence · ${sources} source${sources === 1 ? "" : "s"}`);
331	  }).join("") || `<p class="hint">No requirements yet. The agent proposes them from claims.</p>`;
332	}
333	
334	function setTab(tab) {
335	  sideTab = tab;
336	  for (const b of document.querySelectorAll("[data-tab]")) b.setAttribute("aria-selected", String(b.dataset.tab === tab));
337	  $("#inbox").hidden = tab !== "inbox";
338	  $("#reqs").hidden = tab !== "reqs";
339	}
340	
341	function markSeen() {
342	  lastSeen = graph.nodes.length ? graph.nodes.at(-1).timestamp : new Date().toISOString();
343	  store.set("lastSeen", lastSeen);
344	  renderSide();
345	}
346	
347	// ---- brief + start screen ----------------------------------------------
348	
349	function renderBrief() {
350	  const b = view.brief;
351	  $("#briefbar").innerHTML = !graph.nodes.length ? "" : b
352	    ? `<b>Brief</b><span>${esc(b.content.vehicle ?? "")} · ${esc(b.content.market ?? "")}</span>
353	       <span class="goal">${esc(b.content.text ?? "")}</span>
354	       <button type="button" id="editBrief">Edit brief</button>`
355	    : `<span class="meta">No brief yet: the agent doesn't know your goal.</span>
356	       <button type="button" id="editBrief">Set a brief</button>`;
357	}
358	
359	function openBrief() {
360	  enterMode();
361	  const c = view.brief?.content ?? {};
362	  const opt = (values, cur) => values.map((v) => `<option ${v === cur ? "selected" : ""}>${esc(v)}</option>`).join("");
363	  $("#detail").innerHTML = `
364	    <h2>${view.brief ? "Edit the brief" : "Set a brief"}</h2>
365	    <p class="meta">The agent reads the brief on every run and works towards it.
366	      ${view.brief ? `Saving writes v${view.brief.version + 1} of ${esc(view.brief.id)}.` : ""}</p>
367	    <div class="actions">
368	      <label>Vehicle <select id="briefVehicle">${opt(["BMW 5 Series", "BMW 1 Series", "BMW 7 Series"], c.vehicle)}</select></label>
369	      <label>Market <select id="briefMarket">${opt(["Europe", "China", "United States"], c.market)}</select></label>
370	      <label for="briefText">What should the agent work out?</label>
371	      <textarea id="briefText" rows="4">${esc(c.text ?? "")}</textarea>
372	      <label for="reason">Why (optional)</label>
373	      <textarea id="reason"></textarea>
374	      <div class="row"><button type="button" id="saveBrief" class="primary">Save brief</button>
375	        <button type="button" id="cancelMode">Cancel</button></div>
376	    </div>`;
377	}
378	
379	async function saveBrief() {
380	  const content = { kind: "brief", vehicle: $("#briefVehicle").value, market: $("#briefMarket").value,
381	    text: $("#briefText").value.trim() };
382	  if (!content.text) throw new Error("Write what the agent should work out.");
383	  const rationale = $("#reason").value.trim() || null;
384	  const created = view.brief
385	    ? await api("/edit", { content, target_id: view.brief.id, created_by: pmName(), rationale })
386	    : await api("/nodes", { type: "Note", content, inputs: [], created_by: pmName(), rationale });
387	  toast(`Brief saved (${created.id})`);
388	  showHint();
389	  await load();
390	}
391	
392	// The start screen (start.js) collects the choices; this writes them: brief, sources, first run.
393	// ?start in the URL shows it over an existing graph too (to demo or design it).
394	let forceStart = new URLSearchParams(location.search).has("start");
395	const start = createStart($("#start"), { loadDatasets: () => api("/datasets"), onStart: startProject });
396	
397	async function startProject({ vehicle, market, goal, name, datasets, file, steps }) {
398	  $("#pm").value = name;
399	  store.set("pmName", name);
400	  const by = `PM:${name}`;
401	  await api("/nodes", { type: "Note", inputs: [], created_by: by, rationale: "project brief from the start screen",
402	    content: { kind: "brief", vehicle, market, text: goal } });
403	  for (const f of datasets) await api("/import/dataset", { name: f, created_by: by });
404	  if (file) await api("/import/csv", { filename: file.name, text: await file.text(), created_by: by });
405	  $("#actions").value = steps;
406	  forceStart = false;
407	  await load();
408	  await runAgent();
409	  toast("Agent started: its work appears live; what needs you lands in your inbox.");
410	}
411	
412	// ---- selection + detail panel ------------------------------------------
413	
414	function select(id) {
415	  selected = id;
416	  if (focusMode && focusId !== id) { focusId = id; renderGraph(); }
417	  highlight();
418	  renderSide();
