572	/** Everything (transitively) built on id, including PM decisions on those nodes. */
573	function builtOn(id) {
574	  const seen = new Set();
575	  const todo = [id];
576	  while (todo.length) {
577	    const cur = todo.pop();
578	    const next = [...(view.dependents[cur] || []).map((e) => e.from_id), ...(view.decisionsFor[cur] || []).map((d) => d.id)];
579	    for (const d of next) if (!seen.has(d)) { seen.add(d); todo.push(d); }
580	  }
581	  return [...seen];
582	}
