584	/** One line saying what happened, in PM language. */
585	function describe(n) {
586	  const ins = view.inputs[n.id] || [];
587	  const ids = (rel) => ins.filter((e) => !rel || e.relation === rel).map((e) => chip(e.to_id)).join(" ");
588	  const request = n.content?.request;
589	  if (n.type === "Decision") return `<b>${esc(n.content?.verdict ?? "decided")}</b> ${ids()}`;
590	  if (n.replaces) {
591	    const old = view.byId[n.replaces];
592	    const sameContent = old && JSON.stringify(old.content) === JSON.stringify(n.content);
593	    const stale = builtOn(n.replaces).filter((id) => view.byId[id]?.status === "stale");
594	    return `${sameContent ? "connected a new input to" : "edited"} ${chip(n.replaces)} → v${n.version} ${chip(n.id)}`
595	      + (stale.length ? `<div class="why">now stale because of this: ${stale.map((id) => chip(id)).join(" ")}</div>` : "");
596	  }
597	  if (n.type === "Source") return `imported ${chip(n.id)}`;
598	  if (request) return `asked the agent to <b>${esc(REQUESTS[request])}</b> ${ids()} ${chip(n.id)}`;
599	  if (n.type === "Question") return `asked ${n.created_by.startsWith("PM:") ? "the agent" : "the PM"} ${chip(n.id)}${ins.length ? ` about ${ids()}` : ""}`;
600	  if (n.type === "Note" && ins.some((e) => view.byId[e.to_id]?.type === "Question")) return `answered ${ids()} with ${chip(n.id)}`;
601	  if (ins.some((e) => e.relation === "contradicts")) return `recorded counter-evidence ${chip(n.id)} against ${ids("contradicts")}`;
602	  if (n.type === "Score") return `scored ${ids()} → ${chip(n.id)}`;
603	  return `added ${esc(n.type)} ${chip(n.id)}${ins.length ? ` from ${ids()}` : ""}`;
604	}
