685	// The agent-loop's handled() rule, mirrored: a PM Question/Note is done once the agent built
686	// on it, or — for "challenge" — once the agent built on its target after it was asked.
687	function pmInputDoneBy(n) {
688	  const agentDeps = (id) => (view.dependents[id] || []).map((e) => view.byId[e.from_id])
