/* the three stripes as a small skewed mark */
.mark { display: inline-flex; height: 14px; transform: skewX(-20deg); }
.mark i { width: 4px; } .mark i:nth-child(1) { background: var(--m-light); }
.mark i:nth-child(2) { background: var(--m-dark); } .mark i:nth-child(3) { background: var(--m-red); }

/* Start screen: M stripes flowing like a Sankey diagram on warm paper (see start.js).
   Tokens and the font live in theme.css. Every rule is scoped to .start so it can't leak into
   the workbench (which also has .row, .body, .label, …). */

.start {
  position: fixed; inset: 0; z-index: 50; overflow-y: auto; overscroll-behavior: contain;
  background: var(--paper); color: var(--ink); font-family: var(--type);
  -webkit-font-smoothing: antialiased;
  transition: opacity 450ms cubic-bezier(.2, .8, .2, 1), transform 450ms cubic-bezier(.2, .8, .2, 1), filter 450ms;
}
.start[hidden] { display: none; }
.start.leaving { opacity: 0; transform: scale(1.015); filter: blur(6px); pointer-events: none; }

.start .start-inner {
  position: relative; max-width: 1160px; margin: 0 auto; padding: 0 40px 35vh;
  display: grid; grid-template-columns: 280px minmax(0, 1fr); column-gap: 48px;
}
.start .flow { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; }
.start .flow .stripe { fill: none; stroke-width: 10; stroke-linecap: butt; stroke-linejoin: round; }
.start .flow .s0 { stroke: var(--m-light); } .start .flow .s1 { stroke: var(--m-dark); } .start .flow .s2 { stroke: var(--m-red); }
.start .flow .ghost { fill: none; stroke: var(--ghost); stroke-width: 1.5; }

/* ---- intro: editorial title block between hairlines (left), the stripes run down beside it */
.start .intro { grid-column: 1; padding: 56px 0 8px; }
.start .kicker { display: flex; align-items: center; gap: 10px; margin: 0; padding-bottom: 14px; border-bottom: 1px solid var(--ink);
  font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.start h1 { margin: 22px 0 18px; font-size: 44px; font-weight: 300; line-height: 1.04; letter-spacing: -.025em; }
.start .lede { margin: 0; padding-top: 14px; border-top: 1px solid var(--hair); font-size: 14px; line-height: 1.55; color: var(--muted); }

/* ---- rows: the label sits left, its choice sits on the stripes' path (right) */
.start .row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding-top: 96px; /* = FORK in start.js */ }
.start .row:not(.shown) { opacity: 0; transform: translateY(14px); visibility: hidden; }
.start .row.shown { transition: opacity 500ms cubic-bezier(.2, .8, .2, 1) 140ms, transform 500ms cubic-bezier(.2, .8, .2, 1) 140ms; }
.start .label { display: flex; gap: 12px; align-items: flex-start; }
.start .num { flex: none; display: grid; place-items: center; width: 22px; height: 22px; margin-top: 2px; border-radius: 50%;
  background: var(--ink); color: var(--paper); font-size: 12px; font-weight: 700; }
.start .label h2 { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -.01em; line-height: 1.3; }
.start .label p { margin: 2px 0 0; font-size: 13px; line-height: 1.45; color: var(--muted); }
.start .body { position: relative; display: flex; flex-direction: column; align-items: center; min-width: 0; }

/* cards sit above the stripes and hide them where they flow through */
.start .card { position: relative; z-index: 1; background: var(--paper); }
.start .options { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px 56px; }
.start .opt {
  min-width: 150px; padding: 12px 18px 11px; border: 0; border-top: 2px solid var(--ink); border-radius: 0;
  font: inherit; color: var(--ink); text-align: center; cursor: pointer;
  display: flex; flex-direction: column; gap: 1px;
  transition: background-color 180ms ease, color 180ms ease, transform 100ms ease-out, opacity 180ms ease;
}
.start .opt b { font-size: 15px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
.start .opt span { font-size: 12px; color: var(--muted); letter-spacing: .01em; }
.start .opt:hover { background: var(--hover); }
.start .opt:active { transform: scale(.97); }
.start .opt.on { background: var(--ink); color: #fff; border-top-color: var(--ink); }
.start .opt.on span { color: #b9b6ae; }
.start .opt.off { color: var(--muted); border-top-color: var(--ghost); }
.start .opt.off:hover { color: var(--ink); }
.start .opt:focus-visible, .start .go:focus-visible, .start .brief textarea:focus-visible, .start .field input:focus-visible {
  outline: 2px solid var(--m-light); outline-offset: 3px;
}
.start .loading { color: var(--muted); font-size: 13px; }

.start .brief { display: block; width: min(560px, 100%); padding: 14px 18px 12px; border-top: 2px solid var(--ink); }
.start .eyebrow { display: block; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.start .brief textarea { display: block; width: 100%; margin-top: 6px; padding: 0; border: 0; resize: none; background: none;
  font: 300 19px/1.4 var(--type); letter-spacing: -.01em; color: var(--ink); }
.start .brief textarea:focus { outline: none; }

.start .launch { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: center; gap: 16px 28px; }
.start .field { display: flex; flex-direction: column; gap: 4px; position: relative; z-index: 1; }
.start .field span { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.start .field input { width: 180px; padding: 6px 0; border: 0; border-bottom: 1px solid var(--ink); border-radius: 0; background: none;
  font: 400 16px var(--type); color: var(--ink); }
.start .field.steps input { width: 72px; }
.start .field input:focus { outline: none; border-bottom-color: var(--m-light); }
.start .go {
  position: relative; z-index: 1; min-width: 180px; padding: 15px 28px; border: 0; border-radius: 0;
  background: var(--ink); color: #fff; font: 700 14px var(--type); letter-spacing: .08em; text-transform: uppercase; cursor: pointer;
  transition: transform 100ms ease-out, background-color 180ms ease;
}
.start .go:hover { background: #2a2a2a; }
.start .go:active { transform: scale(.97); }
.start .go:disabled { cursor: progress; }
.start .error { min-height: 1.4em; margin: 14px 0 0; font-size: 13px; color: var(--m-red); text-align: center; }

@media (max-width: 800px) {
  .start .start-inner { grid-template-columns: minmax(0, 1fr); padding: 0 16px 35vh; }
  /* the stripes come out from under the title; each label sits left of them, above the bend */
  .start .row { grid-template-columns: minmax(0, 1fr); padding-top: 28px; row-gap: 96px; /* = FORK */ }
  .start .label { max-width: calc(50% - 28px); }
  .start .intro { position: relative; z-index: 2; padding: 32px 0 24px; background: var(--paper); }
  .start h1 { font-size: 34px; }
  .start .options { gap: 12px 16px; }
  .start .opt { min-width: 120px; }
}
@media (prefers-reduced-motion: reduce) {
  .start, .start .row.shown, .start .opt, .start .go { transition: opacity 200ms ease; }
  .start .row:not(.shown) { transform: none; }
  .start.leaving { transform: none; filter: none; }
}

/* Workbench: graph, inbox, detail panel, audit trail. Ink on paper, colour only in the stripes
   (DESIGN.md). Tokens and the font are in theme.css. */
* { box-sizing: border-box; }
body {
  margin: 0; height: 100vh; display: grid; grid-template-rows: auto 1fr; grid-template-columns: minmax(0, 1fr);
  font: 14px/1.45 var(--type); color: var(--ink); background: var(--paper); -webkit-font-smoothing: antialiased;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { border-radius: 0; }
:focus-visible { outline: 2px solid var(--m-light); outline-offset: 2px; }

/* ---- shared bits: uppercase labels, quiet and primary buttons, underlined fields */
.eyebrow, .field, #detail h3, .group h3, .tabs button, .viewswitch button, .palette summary {
  font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted);
}
.hint, .meta { color: var(--muted); }
.field { display: flex; align-items: center; gap: 8px; min-width: 0; }
.field input, .field select {
  padding: 4px 0; border: 0; border-bottom: 1px solid var(--ink); border-radius: 0; background: none;
  font-size: 14px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ink);
}
.field select { max-width: 220px; }
.field input:focus, .field select:focus { outline: none; border-bottom-color: var(--m-light); }
#actions { width: 3em; }
.primary, .quiet, .group-action, .actions button, .focusbar button, .briefbar button, .palette-items button {
  padding: 7px 14px; border: 1px solid var(--ink); background: var(--paper); cursor: pointer;
  font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  transition: transform 100ms ease-out, background-color 180ms ease, color 180ms ease;
}
.primary { background: var(--ink); color: #fff; }
.primary:hover { background: #2a2a2a; }
.quiet:hover, .group-action:hover, .actions button:hover, .focusbar button:hover, .briefbar button:hover, .palette-items button:hover { background: var(--hover); }
button:active { transform: scale(.97); }
button:disabled { opacity: .5; cursor: progress; }

/* ---- the one top bar */
.topbar {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px;
  padding: 12px 20px; border-bottom: 1px solid var(--ink);
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand h1 { margin: 0; font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.briefbar { flex: 1 1 260px; min-width: 0; display: flex; align-items: baseline; gap: 10px; padding-left: 22px; border-left: 1px solid var(--hair); }
.briefbar .eyebrow { flex: none; }
.briefbar .goal { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 300; font-size: 16px; letter-spacing: -.01em; }
.briefbar button { flex: none; padding: 3px 8px; border-color: var(--hair); }
.viewswitch { display: flex; gap: 16px; }
.viewswitch button { padding: 4px 0; border: 0; border-bottom: 2px solid transparent; background: none; cursor: pointer; }
.viewswitch button[aria-pressed="true"] { color: var(--ink); border-bottom-color: var(--ink); }
.agentbar { display: flex; align-items: center; gap: 12px; position: relative; }
#agentLog summary { cursor: pointer; font-size: 12px; color: var(--muted); white-space: nowrap; list-style: none; }
#agentLog summary::-webkit-details-marker { display: none; }
#agentLog[open] pre {
  position: absolute; right: 0; top: calc(100% + 12px); z-index: 20; width: min(560px, 90vw); max-height: 320px; margin: 0;
  overflow: auto; white-space: pre-wrap; font: 12px/1.5 ui-monospace, Menlo, monospace;
  background: var(--paper); border: 1px solid var(--ink); border-top-width: 2px; padding: 12px;
}

/* ---- three columns: work list, graph, detail */
main { display: grid; grid-template-columns: 300px minmax(0, 1fr) 400px; min-height: 0; position: relative; }
#work { grid-column: 1; grid-row: 1; overflow-y: auto; border-right: 1px solid var(--hair); }
#graphwrap, #timeline { grid-column: 2; grid-row: 1; min-height: 0; }
#detail { grid-column: 3; grid-row: 1; overflow-y: auto; padding: 20px 22px; border-left: 1px solid var(--hair); }

#graphwrap { display: flex; flex-direction: column; position: relative; }
#graphwrap[hidden] { display: none; }
.graphbar { display: flex; align-items: flex-start; gap: 12px; padding: 10px 16px; border-bottom: 1px solid var(--hair); }
.focusbar { flex: 1; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; font-size: 13px; color: var(--muted); }
.focusbar b { color: var(--ink); }
.focusbar button { padding: 4px 10px; }
.focusbar label { display: flex; align-items: center; gap: 6px; }
.palette { flex: none; position: relative; }
.palette summary { cursor: pointer; padding: 5px 0; list-style: none; }
.palette summary::-webkit-details-marker { display: none; }
.palette summary::after { content: " +"; }
.palette[open] summary::after { content: " –"; }
.palette-items {
  position: absolute; right: 0; top: calc(100% + 8px); z-index: 20; width: 300px; display: flex; flex-wrap: wrap; gap: 6px;
  padding: 12px; background: var(--paper); border: 1px solid var(--ink); border-top-width: 2px;
}
.palette-items .meta { flex-basis: 100%; font-size: 12px; }
.palette-items button { cursor: grab; padding: 5px 9px; }
#canvas { position: relative; flex: 1; min-height: 0; }
#graph { position: absolute; inset: 0; }
/* the flow (ghost lines + M stripes) is drawn under the transparent cytoscape canvas, so the
   paper cards hide the stripes where they pass through them */
.graphflow { position: absolute; inset: 0; width: 100%; height: 100%; overflow: hidden; pointer-events: none; }
.graphflow path { fill: none; }
.graphflow .ghost { stroke: var(--ghost); stroke-width: 1.5; }
.graphflow .ghost.contradicts { stroke: var(--ink); stroke-dasharray: 6 5; }
.graphflow .ghost.version { stroke-dasharray: 2 4; }
.graphflow .ghost.faded { opacity: .25; }
.graphflow .stripe { stroke-linecap: butt; stroke-linejoin: round; }
.graphflow .s0 { stroke: var(--m-light); } .graphflow .s1 { stroke: var(--m-dark); } .graphflow .s2 { stroke: var(--m-red); }
.stats { position: absolute; left: 16px; bottom: 10px; margin: 0; font-size: 12px; color: var(--muted); pointer-events: none; }

/* ---- inbox + requirements */
.tabs { display: flex; position: sticky; top: 0; z-index: 1; background: var(--paper); border-bottom: 1px solid var(--hair); }
.tabs button { flex: 1; padding: 12px 6px 10px; border: 0; border-bottom: 2px solid transparent; background: none; cursor: pointer; }
.tabs button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--ink); }
.count { display: inline-block; min-width: 1.6em; margin-left: 4px; padding: 0 4px; font-size: 11px; color: var(--muted); border: 1px solid var(--hair); }
.count:empty { display: none; }
.count.hot { background: var(--ink); border-color: var(--ink); color: #fff; }
#inbox, #reqs { padding: 6px 16px 24px; }
#inbox[hidden], #reqs[hidden] { display: none; }
.group { margin-top: 18px; }
.group h3 { margin: 0 0 4px; padding-bottom: 6px; border-bottom: 1px solid var(--ink); color: var(--ink); }
.group .hint { margin: 6px 0 4px; font-size: 12px; }
.group-action { margin: 6px 0 0; }
.item {
  display: block; width: 100%; padding: 9px 10px 10px; margin: 0; text-align: left; cursor: pointer;
  border: 0; border-bottom: 1px solid var(--hair); background: none;
  transition: background-color 180ms ease, color 180ms ease;
}
.item:hover { background: var(--hover); }
.item.current { background: var(--ink); color: #fff; }
.item.current .why, .item.current .pill { color: #b9b6ae; border-color: #555; }
.item .head { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.item .text { display: block; margin-top: 3px; font-size: 13px; line-height: 1.4; }
.item .why { display: block; margin-top: 3px; font-size: 12px; color: var(--muted); }

/* ---- small uppercase tags: type, verdict, state. No tinted fills (DESIGN.md) */
.pill { display: inline-block; padding: 1px 5px; font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); border: 1px solid transparent; }
.pill.approve { background: var(--ink); color: #fff; }
.item.current .pill.approve { background: #fff; color: var(--ink); }
.pill.reject { border-color: var(--ghost); text-decoration: line-through; }
.pill.postpone { border: 1px dashed var(--ink); color: var(--ink); }
.pill.stale { border-color: var(--m-red); color: var(--m-red); }
.pill.awaiting { border-color: var(--ink); color: var(--ink); }
.pill.none { border-color: var(--hair); }

/* ---- detail panel */
#detail h2 { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 0 4px; padding-bottom: 10px;
  border-bottom: 2px solid var(--ink); font-size: 22px; font-weight: 300; letter-spacing: -.02em; }
#detail h3 { margin: 22px 0 6px; padding-bottom: 4px; border-bottom: 1px solid var(--hair); }
#detail p { margin: 6px 0; }
blockquote { margin: 8px 0; padding: 2px 0 2px 12px; border-left: 2px solid var(--ink); font-weight: 300; font-size: 15px; }
pre.json { white-space: pre-wrap; word-break: break-word; padding: 8px 0; font: 12px/1.5 ui-monospace, Menlo, monospace; color: var(--muted); max-height: 240px; overflow: auto; border-top: 1px solid var(--hair); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { padding: 2px 8px; border: 1px solid var(--hair); background: none; cursor: pointer; font-size: 12px; font-weight: 700; letter-spacing: .04em; }
.chip:hover { border-color: var(--ink); background: var(--hover); }
.decision { border-top: 1px solid var(--hair); padding: 8px 0; font-size: 13px; }
.warn { color: var(--m-red); }
.actions textarea { display: block; width: 100%; min-height: 56px; padding: 6px 0; resize: vertical; border: 0; border-bottom: 1px solid var(--ink); background: none; }
.actions textarea:focus { outline: none; border-bottom-color: var(--m-light); }
.actions .row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.actions button.approve { background: var(--ink); color: #fff; }
.actions button.reject, .actions button.postpone { background: var(--paper); }
.actions details { margin-top: 14px; }
.actions summary { cursor: pointer; font-size: 13px; color: var(--muted); }
.actions label { display: block; margin-top: 12px; font-size: 12px; color: var(--muted); }
.actions select { max-width: 100%; border: 0; border-bottom: 1px solid var(--ink); background: none; padding: 4px 0; }

/* ---- right-click menu */
.menu {
  position: absolute; z-index: 10; display: flex; flex-direction: column; min-width: 240px; padding: 4px 0;
  background: var(--paper); border: 1px solid var(--ink); border-top-width: 2px;
}
.menu[hidden] { display: none; }
.menu button { padding: 7px 14px; border: 0; background: none; text-align: left; cursor: pointer; font-size: 13px; }
.menu button:hover, .menu button:focus-visible { background: var(--ink); color: #fff; outline: none; }

/* ---- audit trail */
#timeline { overflow-y: auto; padding: 16px 24px; }
#timeline[hidden] { display: none; }
.trail-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding-bottom: 12px; border-bottom: 2px solid var(--ink); font-size: 13px; }
#trail { list-style: none; margin: 0; padding: 0; }
.entry { display: grid; grid-template-columns: 160px 1fr; gap: 2px 16px; padding: 12px 8px; border-bottom: 1px solid var(--hair); cursor: pointer; }
.entry:hover { background: var(--hover); }
.entry.current { box-shadow: inset 3px 0 var(--ink); }
.entry time { color: var(--muted); font-size: 12px; }
.entry .actor { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }
.entry .actor.pm { color: var(--ink); }
.entry .body { grid-column: 2; grid-row: 1 / span 2; }
.entry .text { margin-top: 2px; }
.entry .why { color: var(--muted); font-size: 13px; margin-top: 2px; }

#toast { position: fixed; left: 20px; bottom: 20px; z-index: 60; max-width: 480px; }
#toast:not(:empty) { padding: 10px 16px; background: var(--ink); color: #fff; font-size: 13px; }
#toast.error { box-shadow: inset 4px 0 var(--m-red); }

@media (max-width: 800px) {
  body { height: auto; }
  .briefbar { flex-basis: 100%; order: 5; padding-left: 0; border-left: 0; }
  main { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 60vh auto; }
  #work { grid-column: 1; grid-row: 1; max-height: 40vh; border-right: 0; border-bottom: 1px solid var(--hair); }
  #graphwrap, #timeline { grid-column: 1; grid-row: 2; }
  #detail { border-left: 0; border-top: 1px solid var(--ink); grid-column: 1; grid-row: 3; }
  .entry { grid-template-columns: 1fr; } .entry .body { grid-column: 1; grid-row: auto; }
}
@media (prefers-reduced-motion: reduce) {
  button, .item { transition: none; }
}

